/**
 * Unit tests for AbstractCommandLineRunner.doRun()
 */
public class AbstractCommandLineRunner_doRun_TriageGen2Test {

    // Mocking generic types for the abstract class
    private static class MockCompiler extends Compiler {
        @Override public void compile(JSSourceFile[] externs, JSSourceFile[] inputs, CompilerOptions options) {}
        @Override public Result compile(JSSourceFile[] externs, com.google.javascript.jscomp.JSModule[] modules, CompilerOptions options) { return null; }
    }

    private TestRunner runner;
    private CommandLineConfig config;
    private Compiler mockCompiler;
    private CompilerOptions mockOptions;
    private Result mockResult;

    // Concrete implementation of the abstract class for testing
    public static class TestRunner extends AbstractCommandLineRunner<MockCompiler, CompilerOptions> {
        public CommandLineConfig config;
        public Charset inputCharset = StandardCharsets.UTF_8;
        public Writer mockWriter;
        public List<JSSourceFile> mockExterns = Collections.emptyList();
        public List<JSSourceFile> mockInputs = Collections.emptyList();
        public List<com.google.javascript.jscomp.JSModule> mockModules = null;

        @Override protected CommandLineConfig getCommandLineConfig() { return config; }
        @Override protected MockCompiler createCompiler() { return (MockCompiler) getCompiler(); }
        @Override protected CompilerOptions createOptions() { return mockOptions; }
        @Override protected void setRunOptions(CompilerOptions options) throws IOException {}

        // Exposed for testing
        @Override protected List<JSSourceFile> createExterns() throws IOException { return mockExterns; }
        @Override protected List<JSSourceFile> createSourceInputs(List<String> files) throws IOException { return mockInputs; }
        @Override protected com.google.javascript.jscomp.JSModule[] createJsModules(List<String> specs, List<String> files) { return mockModules; }

        // Mocking internal accessors/fields via spy/override logic
        protected int processResults(Result result, com.google.javascript.jscomp.JSModule[] modules, CompilerOptions options) { return 0; }

        // Helper to simulate the 'out' field which is protected in the base class
        public void setOut(Writer out) { this.out = out; }

        // Required overrides for the abstract class structure
        @Override protected com.google.javascript.jscomp.DiagnosticGroups getDiagnosticGroups() { return null; }
        @Override protected void initOptionsFromFlags(CompilerOptions options) {}

        // Since we can't easily inject 'out' if it's private/protected without reflection, 
        // we assume the runner uses a method to set it or we use a subclass that exposes it.
        // In this context, we assume 'out' is accessible to the subclass.
    }

    @Before
    @SuppressWarnings("unchecked")
    public void setUp() throws Exception {
        runner = spy(new TestRunner());
        config = mock(CommandLineConfig.class);
        mockCompiler = mock(MockCompiler.class);
        mockOptions = mock(CompilerOptions.class);
        mockResult = mock(Result.class);

        runner.config = config;
        runner.setOut(null); // Reset

        doReturn(mockCompiler).when(runner).getCompiler();
        doReturn(mockOptions).when(runner).createOptions();

        // Default config behavior
        when(config.loggingLevel).thenReturn("INFO");
        when(config.js).thenReturn(Collections.singletonList("file.js"));
        when(config.module).thenReturn(Collections.emptyList());

        // Default options behavior
        when(mockOptions.jsOutputFile).thenReturn("");

        // Setup processResults to return 0
        doReturn(0).when(runner).processResults(any(), any(), any());
    }

    @Test
    public void testDoRun_StandardInputs_NoModules_UTF8() throws Exception {
        runner.inputCharset = StandardCharsets.UTF_8;
        when(mockCompiler.compile(any(), any(), any())).thenReturn(mockResult);

        int result = runner.doRun();

        assertEquals(0, result);
        verify(mockCompiler).compile(any(), any(), any());
    }

    @Test
    public void testDoRun_StandardInputs_NoModules_OtherCharset() throws Exception {
        runner.inputCharset = StandardCharsets.ISO_8859_1;
        when(mockCompiler.compile(any(), any(), any())).thenReturn(mockResult);
        when(mockOptions.outputCharset).thenReturn(StandardCharsets.ISO_8859_1);

        int result = runner.doRun();

        assertEquals(0, result);
        verify(mockOptions).outputCharset = StandardCharsets.ISO_8859_1;
    }

    @Test
    public void testDoRun_WithModules() throws Exception {
        runner.inputCharset = StandardCharsets.UTF_8;
        List<String> moduleSpecs = Collections.singletonList("mod.js");
        when(config.module).thenReturn(moduleSpecs);

        com.google.javascript.jscomp.JSModule[] modules = new com.google.javascript.jscomp.JSModule[0];
        runner.mockModules = Arrays.asList(modules);
        when(mockCompiler.compile(any(), any(), any())).thenReturn(mockResult);

        int result = runner.doRun();

        assertEquals(0, result);
        verify(mockCompiler).compile(any(), any(), any());
    }

    @Test
    public void testDoRun_WriteToFile() throws Exception {
        runner.inputCharset = StandardCharsets.UTF_8;
        when(mockOptions.jsOutputFile).thenReturn("output.js");
        when(mockCompiler.compile(any(), any(), any())).thenReturn(mockResult);

        Writer mockWriter = mock(Writer.class);
        // We need to bypass toWriter which is likely protected/internal. 
        // In a real test, we'd use a spy to return the mockWriter.
        doReturn(mockWriter).when(runner).toWriter(any(), any());
        runner.setOut(mockWriter);

        int result = runner.doRun();

        assertEquals(0, result);
        verify(mockWriter).close();
    }

    @Test
    public void testDoRun_ProcessResultsError() throws Exception {
        when(mockCompiler.compile(any(), any(), any())).thenReturn(mockResult);
        doReturn(1).when(runner).processResults(any(), any(), any());

        int result = runner.doRun();

        assertEquals(1, result);
    }
}

// Mocking the config structure as it's not provided
interface CommandLineConfig {
    String getLoggingLevel();
    String getJs(); // This should be a list in actual code, adjusting to match logic
    List<String> getJsList(); 
    List<String> getModule();
}

